"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[7964],{1160(a){a.exports=JSON.parse('{"title":"\ub2f9\uc2e0\uc740 N \ud504\ub808\uc784\uc6cc\ud06c\uac00 \ud544\uc694\uc5c6\uc744 \uc218\ub3c4 \uc788\ub2e4.","date":"2024-02-14","coverUrl":null,"html":"<h2 data-notion-block-id=\\"7c1d24d4-7951-46a1-9da2-ef596dda3157\\" id=\\"7c1d24d4-7951-46a1-9da2-ef596dda3157\\">\ub2f9\uc2e0\uc740 N \ud504\ub808\uc784\uc6cc\ud06c\uac00 \ud544\uc694\uc5c6\uc744 \uc218\ub3c4 \uc788\ub2e4.</h2><a href=\\"https://piccalil.li/blog/react-is-getting-a-bit-of-a-kicking-recently/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://piccalil.li/blog/react-is-getting-a-bit-of-a-kicking-recently/</a><p data-notion-block-id=\\"468ccc76-81a2-4ea8-a878-0bc44b3e210a\\"><b>\uc2ec\uc724\uc12d</b>: \uc2dc\uc791\uc740 React\ub97c \uc4f0\uc9c0 \ub9d0\uc544\uc57c \ud55c\ub2e4\ub77c\uace0 \ud558\ub294 <a href=\\"https://begin.com/blog/posts/2024-01-26-removing-react-is-just-weakness-leaving-your-codebase\\">\uac8c\uc2dc\uae00</a>\uc5d0 \ub300\ud55c \ubc18\ubc15\uc774\uc9c0\ub9cc \ub0b4\uc6a9\uc740 \\"\uae30\uc220 \uc2a4\ud0dd\uc744 \uc815\ud560 \ub54c \uc790\uc2e0\uc758 \ud300 \uc0c1\ud669\uacfc \ubc1c\uc0dd\ud560 \uc218 \uc788\ub294 \ucd5c\uc545\uc758 \uc218\ub97c \uace0\ub824\ud558\ub77c\\"\uc785\ub2c8\ub2e4. \uac04\ub2e8\ud55c \uc6f9\uc0ac\uc774\ud2b8\ub97c \ub9cc\ub4e4 \ub54c React\uac00 \ud544\uc694\ud560 \uc218\ub3c4, \ud544\uc694 \uc5c6\uc744 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub2e8\uc21c\ud788 \uc774 \uae30\uc220\uc774 \uc88b\uc544\ubcf4\uc774\ubbc0\ub85c \uc120\ud0dd\ud558\ub294 \uacb0\uc815\uc740 \uc88b\uc544\ubcf4\uc774\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"7cf7233e-e00d-4a70-86e8-96708a783e71\\"><b>\uae40\ub300\uad00</b>: \uc6b0\ub9ac\ub4e4\uc740 \uba74\uc811 \uc9c8\ubb38 \uc911\uc5d0 ~~\uc744 \uc65c \uc0ac\uc6a9\ud558\uc600\ub294\uac00? \ub77c\ub294 \uc9c8\ubb38\uc744 \ubc1b\ub294 \uacbd\uc6b0\uac00 \uc788\ub294\ub370, \uc774\ub97c \uc9c8\ubb38\ud558\ub294 \ubaa9\uc801\uc740 \uc5d4\uc9c0\ub2c8\uc5b4\ub85c \ud574\ub2f9 \uae30\uc220\uc744 \uc0ac\uc6a9\ud558\uac8c \ub41c \ud310\ub2e8\uc758 \uadfc\uac70\ub97c \ubb3b\ub294 \uc9c8\ubb38\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ud574\ub2f9 \uae00\uc5d0\uc11c \uaf2c\uc9d1\ub294 \uac83\ucc98\ub7fc \ud2b8\uc704\ud130\ub098 \ube14\ub85c\uadf8\uc5d0\uc11c \ub2e8\uc21c\ud558\uac8c \uc774\uac78 \ud65c\uc6a9\ud558\ub354\ub77c\ub77c\ub294 \uc774\uc720\ubcf4\ub2e4\ub294 \ud604\uc7ac \uae30\uc220 \uc0c1\ud669\uc5d0 \ub300\ud55c \uc815\ud655\ud55c \ud310\ub2e8 \uadfc\uac70\ub97c \uc0dd\uac01\ud558\uace0 \uc790\uc2e0\uc758 \uadfc\uac70\ub97c \ud655\uc2e4\ud558\uac8c \uc7a1\ub294 \uac83\uc774 \uc5d4\uc9c0\ub2c8\uc5b4\ub85c \uc911\uc694\ud55c \ub355\ubaa9\uc77c \uac83\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"43ce9d85-1b0b-4bf7-ac04-90a077f8980e\\" id=\\"43ce9d85-1b0b-4bf7-ac04-90a077f8980e\\">\uacb0\uc81c \uc2dc\uc2a4\ud15c \ub9ac\ud329\ud1a0\ub9c1\uc744 \ud1b5\ud55c \ubcf5\uc7a1\uc131 \ud574\uc18c, \uadf8\ub7fc\uc5d0\ub3c4 \ub098\uc624\ub294 \ub2e8\uc810</h2><a href=\\"https://commerce.nearform.com/blog/2024/tale-of-a-refactor/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://commerce.nearform.com/blog/2024/tale-of-a-refactor/</a><p data-notion-block-id=\\"6b48fc28-9cd4-47c8-aa17-df410ac415a7\\"><b>\uc2ec\uc724\uc12d</b>: \uacb0\uc81c \uc2dc\uc2a4\ud15c\uc744 \uad6c\ud604\ud558\uace0 \uc774\ub97c \ub9ac\ud329\ud1a0\ub9c1\ud558\uba74\uc11c \ucd94\uc0c1\ud654\uc758 \uacfc\uc815\uc744 \uc798 \uc124\uba85\ud574\uc900 \uac8c\uc2dc\uae00\uc785\ub2c8\ub2e4. \uc774 \uae00\uc740 \uc811\uadfc \ubc29\uc2dd\uc744 \uc798 \uc124\uba85\ud574\uc11c \ucd94\uc0c1\ud654\uac00 \uc5b4\ub5bb\uac8c \uc774\ub8e8\uc5b4\uc838\uc57c \ud558\uba70, \ucd94\uc0c1\ud654\uc5d0 \ub300\ud55c \uc704\ud5d8\uc131\ub3c4 \uc798 \uc54c\ub824\uc900\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \uac1c\uc778\uc801\uc73c\ub85c\ub294 <a href=\\"https://kentcdodds.com/blog/aha-programming\\">Kent C. Dodd\uc528\uc758 \uc811\uadfc\ubc29\uc2dd</a>\uc774 \uadf8\uc5d0 \ub300\ud55c \uc704\ud5d8\uc131\uc744 \uc798 \uc54c\ub824\uc900\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"5fa3cabc-1310-44f5-ba24-dd0e0ba232f1\\" id=\\"5fa3cabc-1310-44f5-ba24-dd0e0ba232f1\\">\uc2dc\uac04\uc740 \ub3c8\uc774\ub77c\uad6c \uce5c\uad6c.</h2><a href=\\"https://www.speedcurve.com/blog/psychology-site-speed/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.speedcurve.com/blog/psychology-site-speed/</a><p data-notion-block-id=\\"a044ea8c-0815-4b6f-a9d6-736d422e94b6\\"><b>\uc2ec\uc724\uc12d</b>: \uc6f9\uc0ac\uc774\ud2b8\uac00 \ub290\ub9ac\uba74 \uace0\uac1d\uc5d0\uac8c \ubc1c\uc0dd\ud558\ub294 \uc77c\uc744 \uc5ec\ub7ec \uadfc\uac70\ub97c \ud1b5\ud574 \uc124\uba85\ud569\ub2c8\ub2e4. \uc774\ub7f0 \uace0\uac1d\uc758 \uacbd\ud5d8 \uc678\uc5d0\ub3c4 \uad6c\uae00 \uac80\uc0c9 \uc21c\uc704, \uc804\ud658\uc728\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubbf8\uce58\ubbc0\ub85c <a href=\\"https://web.dev/blog/inp-cwv-march-12?hl=ko\\">\ud1b5\uacc4\uc640 \ud568\uaed8 Web Vitals \ud5a5\uc0c1</a>\uc744 \ub193\uce58\uc9c0 \uc54a\uc558\uc73c\uba74 \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"9b38e19c-e876-454b-8b95-6b84b89ebcf9\\" id=\\"9b38e19c-e876-454b-8b95-6b84b89ebcf9\\">TypeScript\uc5d0\uc11c\uc758 \ud301</h2><a href=\\"https://www.totaltypescript.com/method-shorthand-syntax-considered-harmful\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.totaltypescript.com/method-shorthand-syntax-considered-harmful</a><a href=\\"https://www.totaltypescript.com/as-never\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.totaltypescript.com/as-never</a><p data-notion-block-id=\\"cddf9831-dd07-4ad1-95e9-84442200ff6f\\"><b>\uc2ec\uc724\uc12d</b>: TypeScript\ub97c \uae4a\uac8c \uacf5\ubd80\ud558\ub2e4\ubcf4\uba74 \ubb34\uc870\uac74 \ub098\uc624\ub294 <a href=\\"https://seob.dev/posts/%EA%B3%B5%EB%B3%80%EC%84%B1%EC%9D%B4%EB%9E%80-%EB%AC%B4%EC%97%87%EC%9D%B8%EA%B0%80/\\">\uc774\ubcc0\uc131</a>\uc774\ub77c\ub294 \uac1c\ub150\uacfc \ud568\uaed8 \uba54\uc18c\ub4dc \ucd95\uc57d \uad6c\ubb38\uc744 \uc0ac\uc6a9\ud558\uc9c0 \ub9d0\ub77c\ub294 \uae00\uacfc <code>as never</code>\ub97c \uc0ac\uc6a9\ud574\uc57c \ud558\ub294 \uacbd\uc6b0\ub97c \uc18c\uac1c\ud574\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\ubcc0\uc131\uc774\ub77c\ub294 \uac1c\ub150\uc744 \ubaa8\ub978\ub2e4\uba74 \uc81c\uc2dc\ub41c \ub9c1\ud06c\ub97c \ubaa8\ub450 \uc77d\uc5b4\ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"6baca55e-a6e9-46f5-a89a-c365bc5df5b2\\" id=\\"6baca55e-a6e9-46f5-a89a-c365bc5df5b2\\">Nuxt\ub294 \uac1c\ubc1c\ud658\uacbd\uc5d0\uc11c SSR \ubc88\ub4e4\ub9c1\uc744 \uc5b4\ub5bb\uac8c \uac1c\uc120\ud588\ub294\uac00</h2><a href=\\"https://antfu.me/posts/dev-ssr-on-nuxt\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://antfu.me/posts/dev-ssr-on-nuxt</a><p data-notion-block-id=\\"94724427-cd9b-4d0f-903a-c4de8b5188c6\\"><b>\uc2ec\uc724\uc12d</b>: Vite 5.1\uc774 \ucd9c\uc2dc\ub418\uba74\uc11c \ub9c1\ud06c\ub41c \uae00\uc774 \ucc38\uace0\ud560 \ub9cc\ud558\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ub9cc\ub4e4 \ub54c\ub294 \ud544\uc694 \uc5c6\uc9c0\ub9cc \ubc14\ud034\ub97c \ub2e4\uc2dc \ub9cc\ub4e4\uc9c0\ub294 \ubaa8\ub974\uc796\uc544\uc694?</p><h2 data-notion-block-id=\\"5f5c2309-55aa-4509-9907-92b87e808d97\\" id=\\"5f5c2309-55aa-4509-9907-92b87e808d97\\"><code>composedPath</code>\uc5d0 \ub300\ud55c \uc18c\uac1c</h2><a href=\\"https://spacejelly.dev/posts/how-to-detect-clicks-anywhere-on-a-page-in-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://spacejelly.dev/posts/how-to-detect-clicks-anywhere-on-a-page-in-react</a><p data-notion-block-id=\\"2ed2f39d-8a10-433c-96cf-870bdf9d846a\\">\\"\ub9ac\uc561\ud2b8\uc5d0\uc11c\\"\uac00 \ubd99\uc5b4\uc788\uc9c0\ub9cc \ub2e4\ub978 \uc21c\uc218 JS\uc5d0\ub3c4 \uc801\uc6a9\ud560 \uc218 \uc788\ub294 \uc88b\uc740 \uae30\ub2a5\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p>"}')}}]);